__NUXT_JSONP__("/ru/teachers", {data:[{details:{slug:"ru",pageTitle:"MLI Классы и Учителя | Mentor Language Institute",pageDescription:"На курсах общего английского, студенты приобретают практические навыки, используя материалы реального мира, такие как сообщения в Twitter,  TED и видеоклипы.",title:"MLI Классы и Учителя",image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fmli-student-teachers.jpg",lists:[{title:"Классы сосредоточены на практических навыках",description:["На курсах общего английского, студенты приобретают практические навыки, используя материалы реального мира, такие как сообщения в Twitter,  TED и видеоклипы. Используя эти материалы, студенты систематически приобретают навыки грамматики, письма, чтения, словарного запаса, аудирования и речи.","Кроме того, TOEFL® и другие курсы по подготовке к академическим экзаменам предоставляют стратегии для решения тестов."]},{title:"Учителя MLI",description:["Ежегодно 1200 студентов заканчивают курсы в MLI, что говорит о качестве наших педагогов. Мы постоянно стремимся улучшить навыки преподавателей с помощью наблюдений, оценок и семинаров по профессиональному развитию."],checklist:[{title:"Требования к найму (контрольный список для найма учителей)",lists:["Выпускник четырехгодичного колледжа","3-летний опыт работы в качестве учителя английского языка","Преподавательская квалификация, такая как TESOL","Знание экзаменационных тестов, таких как TOEFL® \u002F GMAT®","Сильные коммуникативные навыки","Страсть и приверженность к обучению"]},{title:"Метод отбора",lists:["Резюме и диплом","Грамматический тест по английскому языку","Интервью","Модель урока"],note:"Уровень найма составляет менее 20%."}]},{title:"Система обучения и оценки",description:["В MLI оцениваются следующие три краитерия каждые 12 недель, для сохранения качества учителей."],listType:"decimal",lists:["Учащиеся оценивают учебники и учителей. Учителя со степенью удовлетворенности 85% или менее проходят профессиональную подготовку.","Наблюдения за уроками и отзывы, предоставленные старшей академической командой.","Профессиональные семинары для повышения квалификации и обучения."],note:"Руководство и учителя стремятся ежедневно повышать качество образования!"}],teachers:[{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-julie.jpg",name:"Julie"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-brian.jpg",name:"Brian"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-kelsey.jpg",name:"Kelsey"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-shawna.jpg",name:"Shawna"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-benjamin.jpg",name:"Benjamin"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-kyle.jpg",name:"Kyle"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-lindsay.jpg",name:"Lindsay"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-leo.jpg",name:"Leo"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-alex.jpg",name:"Alex"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-carl.jpg",name:"Carl"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-shenna.jpg",name:"Shenna"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-bonnie.jpg",name:"Bonnie"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-patrick.jpg",name:"Patrick"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-hubert.jpg",name:"Hubert"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-matt.jpg",name:"Matt"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Maribel.jpg",name:"Maribel"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Joan.jpg",name:"Joan"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Sara.jpg",name:"Sara"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Tom.jpg",name:"Tom"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Gannon.jpg",name:"Gannon"}],dir:"\u002Fteachers",path:"\u002Fteachers\u002Fru",extension:".json",createdAt:"2026-10-22T16:31:31.177Z",updatedAt:"2025-05-26T12:06:27.932Z"}}],fetch:{},mutations:void 0});